import{_ as t,o,c,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2026-01-21","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2026-01-21","date":"2026-01-21T00:00:00.000Z","updated":"2026-01-26T00:00:00.000Z","tags":["RGW","S3 Vectors","multisite","重构","集成测试"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Ceph_RGW_Refactoring_Meeting_2026-01-21.md","filePath":"posts/2026/Ceph_RGW_Refactoring_Meeting_2026-01-21.md","lastUpdated":1780460162000}'),r={name:"posts/2026/Ceph_RGW_Refactoring_Meeting_2026-01-21.md"};function i(l,e,s,d,n,u){return o(),c("div",null,[...e[0]||(e[0]=[a('<h2 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h2><p>本次 RGW 重构会议主要围绕两个议题展开：S3 Vectors API 中vector bucket 的实现方案，以及 multisite 测试套件从 boto2 迁移到 boto3 的工作进展。</p><h2 id="议题一-s3-vectors-api-—-vector-bucket-实现方案" tabindex="-1">议题一：S3 Vectors API — Vector Bucket 实现方案 <a class="header-anchor" href="#议题一-s3-vectors-api-—-vector-bucket-实现方案" aria-label="Permalink to &quot;议题一：S3 Vectors API — Vector Bucket 实现方案&quot;">​</a></h2><h3 id="背景与目标" tabindex="-1">背景与目标 <a class="header-anchor" href="#背景与目标" aria-label="Permalink to &quot;背景与目标&quot;">​</a></h3><p>发言人介绍了正在进行的 S3 Vectors API 实现工作。S3 Vectors API 的顶层实体是 <strong>vector bucket</strong>，它与普通 S3 bucket 有诸多相似之处，但也存在关键差异：</p><ul><li>vector bucket 不包含 objects</li><li>vector bucket 没有 bucket index</li><li>其余特性如 bucket policy、ownership校验、authentication/authorization、multisite 支持、bucket 创建/删除、bucket 列表等与普通 bucket 类似</li></ul><p>实现目标是在尽量减少代码重复的同时，也尽量减少对现有代码的侵入性改动，在两者之间寻求平衡。</p><h3 id="架构设计" tabindex="-1">架构设计 <a class="header-anchor" href="#架构设计" aria-label="Permalink to &quot;架构设计&quot;">​</a></h3><p><strong>Cell 层（RGW Cell）</strong></p><p>在 driver 层新增两个函数：</p><ul><li><code>load_vector_bucket</code>：对应现有的 <code>load_bucket</code></li><li><code>list_vector_buckets</code>：对应现有的 <code>list_buckets</code></li></ul><p>新增抽象类 <code>vector_bucket</code>，作为 bucket cell 类的子集，提供 <code>create、</code>remove<code>、</code>get_attrs<code>、</code>set_attrs` 等接口。</p><p>关键设计决策：复用现有的 <code>bucket_info</code> 对象，不引入继承或多态。虽然 <code>bucket_info</code> 中部分字段对 vector bucket 无意义（如 resharding、layout 等），但复用它极大地减少了其他模块的改动量。未来可能会为 vector bucket 添加 stats/usage 等 admin 功能。</p><p><strong>RADOS 实现层</strong></p><ul><li>为 vector bucket 新增独立的 pool，以便存储特性可以独立配置</li><li>新增 <code>create_vector_bucket</code> 和 <code>delete_vector_bucket</code> 函数，代码基本从对应的普通 bucket 函数 copy-paste 而来，主要差异在于操作的是 <code>control.vector_bucket</code> 而非 <code>control.bucket</code></li><li>bucket controller 同时持有 <code>bucket</code> 和 <code>vector_bucket</code> 两个对象，避免引入新的多态层级（原 controller 本身无多态行为）</li></ul><p><strong>SVC Bucket 层（<code>svc_bucket_sobj</code>）</strong></p><p>该层已有多态设计，因此顺势扩展：</p><ul><li>新增 <code>RGWSI_VectorBucket_SObj</code> 继承自 <code>RGWSI_Bucket_SObj</code></li><li>主要差异通过 virtual 函数实现： <ul><li><strong>oid prefix</strong>：vector bucket 使用不同的对象名前缀（如 <code>vectorbucket.meta</code>），确保同名的普通 bucket 与 vector bucket 不冲突</li><li><strong>cache key</strong>：使用不同前缀（如 <code>VBI/</code> 替代 <code>BI/</code>）避免缓存混淆</li><li><strong>pool</strong>：使用 vector bucket 专属 pool</li><li><strong>metadata sync section</strong>：新增独立的 <code>vector_bucket</code> section，与 <code>bucket</code> section 分开同步</li></ul></li></ul><p><strong>Metadata Sync 层</strong></p><ul><li>复用现有的多态结构，新增 <code>VectorBucketInstanceMetadataHandler</code> 继承自现有 handler</li><li>将两个原本非 virtual 的函数改为 virtual，在派生类中 override 为空操作，因为 vector bucket 没有 bucket index，无需同步 index</li></ul><p><strong>服务初始化</strong></p><p>在 <code>RGWServices</code> 的 service definition 中同时注册 <code>bucket_sobj</code> 和 <code>vector_bucket_sobj</code>，<code>control.bucket</code> 返回前者，<code>control.vector_bucket</code> 返回后者。</p><h3 id="集成测试" tabindex="-1">集成测试 <a class="header-anchor" href="#集成测试" aria-label="Permalink to &quot;集成测试&quot;">​</a></h3><p>当前 PR 的集成测试覆盖：</p><ul><li>vector bucket 的创建与删除</li><li>同名 vector bucket 与普通 bucket 并存</li><li>各种顺序的删除操作</li></ul><p>确保新增功能不干扰现有行为。</p><h3 id="与lancedb-pr-的关系" tabindex="-1">与LanceDB PR 的关系 <a class="header-anchor" href="#与lancedb-pr-的关系" aria-label="Permalink to &quot;与LanceDB PR 的关系&quot;">​</a></h3><p>vector bucket 是顶层实体，实际的向量存储、索引创建、向量写入、查询搜索等功能由另一个互补 PR 实现（集成 LanceDB）。两个 PR 相对正交，LanceDB PR 不依赖 vector bucket 的内部机制，与 RGW 内部耦合较低。</p><h3 id="代码注释问题" tabindex="-1">代码注释问题 <a class="header-anchor" href="#代码注释问题" aria-label="Permalink to &quot;代码注释问题&quot;">​</a></h3><p>与会者 Igor 指出新增类缺乏注释，导致需要阅读代码才能理解类之间的差异。发言人认可这一反馈，承诺为新增的类和公共方法补充文档注释。</p><h2 id="议题二-multisite-测试-—-boto2-迁移至-boto3" tabindex="-1">议题二：Multisite 测试 — boto2 迁移至 boto3 <a class="header-anchor" href="#议题二-multisite-测试-—-boto2-迁移至-boto3" aria-label="Permalink to &quot;议题二：Multisite 测试 — boto2 迁移至 boto3&quot;">​</a></h2><h3 id="问题背景" tabindex="-1">问题背景 <a class="header-anchor" href="#问题背景" aria-label="Permalink to &quot;问题背景&quot;">​</a></h3><p>Shelpa 介绍了 multisite 测试套件的现状：Moto 2（boto2）已损坏，相关测试无法正常运行。</p><h3 id="当前进展" tabindex="-1">当前进展 <a class="header-anchor" href="#当前进展" aria-label="Permalink to &quot;当前进展&quot;">​</a></h3><p>已提交 draft PR，开始将测试从 boto2 迁移至 boto3：</p><ul><li>对于需要比较 objects 和 buckets 的 zone 文件，改用 S3 resource API</li><li>测试本身计划改用 S3 client API</li></ul><p>欢迎社区成员参与贡献或协助测试。</p><h3 id="关于迁移至-pytest的讨论" tabindex="-1">关于迁移至 pytest的讨论 <a class="header-anchor" href="#关于迁移至-pytest的讨论" aria-label="Permalink to &quot;关于迁移至 pytest的讨论&quot;">​</a></h3><p>与会者提出是否可以同步将测试框架从 nose 迁移至 pytest（nose 已是停止维护的框架）。</p><p>发言人解释了之前尝试 pytest 的障碍：multisite 测试的执行方式较为特殊，测试需要在 teuthology task 内部运行，以便访问 teuthology 的远程 API，从而在不同主机上发出命令。在该环境下无法让 pytest 正常工作，因此目前仍保留 nose。如有兴趣，可以提供相关文件和历史 PR 作为参考。</p><h2 id="后续行动" tabindex="-1">后续行动 <a class="header-anchor" href="#后续行动" aria-label="Permalink to &quot;后续行动&quot;">​</a></h2><ul><li><strong>vector bucket PR</strong>：请感兴趣的开发者审阅 PR 并提交反馈；发言人将为新增类补充代码注释</li><li><strong>boto3 迁移 PR</strong>：欢迎社区参与，Shelpa 将持续推进迁移工作</li><li><strong>pytest 迁移</strong>：作为潜在后续工作，需要解决 teuthology 环境下的调用问题</li></ul>',42)])])}const h=t(r,[["render",i]]);export{p as __pageData,h as default};
